    for (int i = 0; i < 32; ++i) {
        float sum = nn_b1[i];
        for (int j = 0; j < 32; ++j) sum += nn_w1[i * 32 + j] * h0[j];
        h1[i] = (sum > 0.0f) ? sum : 0.0f;  // ReLU
    }

    // Output layer (linear)
    for (int i = 0; i < 2; ++i) {
        float sum = nn_b2[i];
        for (int j = 0; j < 32; ++j) sum += nn_w2[i * 32 + j] * h1[j];
        output[i] = sum;
    }
